CREATE TABLE IF NOT EXISTS drawing_occurrence_cluster_versions (id TEXT PRIMARY KEY,project_id TEXT NOT NULL,document_id TEXT NOT NULL,approved_geometry_version_id TEXT NOT NULL,source_recognition_version_id TEXT NOT NULL,version_number INTEGER NOT NULL,input_fingerprint TEXT NOT NULL,output_fingerprint TEXT NOT NULL,engine_version TEXT NOT NULL,status TEXT NOT NULL,summary TEXT NOT NULL,created_by TEXT NOT NULL,superseded_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX IF NOT EXISTS drawing_occurrence_cluster_version_idx ON drawing_occurrence_cluster_versions(document_id,version_number);
CREATE TABLE IF NOT EXISTS drawing_occurrence_spatial_clusters (id TEXT PRIMARY KEY,cluster_version_id TEXT NOT NULL,page_number INTEGER NOT NULL,bounding_box TEXT NOT NULL,source_occurrence_ids TEXT NOT NULL,fragments TEXT NOT NULL,fragment_count INTEGER NOT NULL,raw_signature TEXT NOT NULL,normalized_signature TEXT NOT NULL,topology TEXT NOT NULL,hole_count INTEGER NOT NULL,detection_confidence INTEGER NOT NULL,detection_basis TEXT NOT NULL,exclusion_reasons TEXT NOT NULL,match_similarity INTEGER NOT NULL DEFAULT 0,match_basis TEXT,geometry_differences TEXT NOT NULL DEFAULT '[]',review_status TEXT NOT NULL,reviewed_by TEXT,reviewed_at TEXT,review_reason TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX IF NOT EXISTS drawing_occurrence_spatial_cluster_idx ON drawing_occurrence_spatial_clusters(cluster_version_id,page_number,raw_signature);
CREATE TABLE IF NOT EXISTS drawing_occurrence_cluster_events (id TEXT PRIMARY KEY,project_id TEXT NOT NULL,document_id TEXT NOT NULL,cluster_version_id TEXT NOT NULL,cluster_id TEXT NOT NULL,action TEXT NOT NULL,previous_value TEXT NOT NULL,new_value TEXT NOT NULL,reason TEXT NOT NULL,actor_user_id TEXT NOT NULL,request_id TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS drawing_occurrence_cluster_event_idx ON drawing_occurrence_cluster_events(cluster_id,created_at);
